1	import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
2	import { and, eq, isNull, sql } from "drizzle-orm";
3	import type { Db } from "@paperclipai/db";
4	import {
5	  authUsers,
6	  boardApiKeys,
7	  cliAuthChallenges,
8	  companies,
9	  companyMemberships,
10	  instanceUserRoles,
11	} from "@paperclipai/db";
12	import { conflict, forbidden, notFound } from "../errors.js";
13	
14	export const BOARD_API_KEY_TTL_MS = 30 * 24 * 60 * 60 * 1000;
15	export const CLI_AUTH_CHALLENGE_TTL_MS = 10 * 60 * 1000;
16	
17	export type CliAuthChallengeStatus = "pending" | "approved" | "cancelled" | "expired";
18	
19	export function hashBearerToken(token: string) {
20	  return createHash("sha256").update(token).digest("hex");
21	}
22	
23	export function tokenHashesMatch(left: string, right: string) {
24	  const leftBytes = Buffer.from(left, "utf8");
25	  const rightBytes = Buffer.from(right, "utf8");
26	  return leftBytes.length === rightBytes.length && timingSafeEqual(leftBytes, rightBytes);
27	}
28	
29	export function createBoardApiToken() {
30	  return `pcp_board_${randomBytes(24).toString("hex")}`;
31	}
32	
33	export function createCliAuthSecret() {
34	  return `pcp_cli_auth_${randomBytes(24).toString("hex")}`;
35	}
36	
37	export function boardApiKeyExpiresAt(nowMs: number = Date.now()) {
38	  return new Date(nowMs + BOARD_API_KEY_TTL_MS);
39	}
40	
41	export function cliAuthChallengeExpiresAt(nowMs: number = Date.now()) {
42	  return new Date(nowMs + CLI_AUTH_CHALLENGE_TTL_MS);
43	}
44	
45	function challengeStatusForRow(row: typeof cliAuthChallenges.$inferSelect): CliAuthChallengeStatus {
46	  if (row.cancelledAt) return "cancelled";
47	  if (row.expiresAt.getTime() <= Date.now()) return "expired";
48	  if (row.approvedAt && row.boardApiKeyId) return "approved";
49	  return "pending";
50	}
51	
52	export function boardAuthService(db: Db) {
53	  async function resolveBoardAccess(userId: string) {
54	    const [user, memberships, adminRole] = await Promise.all([
55	      db
56	        .select({
57	          id: authUsers.id,
58	          name: authUsers.name,
59	          email: authUsers.email,
60	        })
61	        .from(authUsers)
62	        .where(eq(authUsers.id, userId))
63	        .then((rows) => rows[0] ?? null),
64	      db
65	        .select({
66	          companyId: companyMemberships.companyId,
67	          membershipRole: companyMemberships.membershipRole,
68	          status: companyMemberships.status,
69	        })
70	        .from(companyMemberships)
71	        .where(
72	          and(
73	            eq(companyMemberships.principalType, "user"),
74	            eq(companyMemberships.principalId, userId),
75	            eq(companyMemberships.status, "active"),
76	          ),
77	        )
78	        .then((rows) => rows),
79	      db
80	        .select({ id: instanceUserRoles.id })
81	        .from(instanceUserRoles)
82	        .where(and(eq(instanceUserRoles.userId, userId), eq(instanceUserRoles.role, "instance_admin")))
83	        .then((rows) => rows[0] ?? null),
84	    ]);
85	
86	    return {
87	      user,
88	      companyIds: memberships.map((row) => row.companyId),
89	      memberships,
90	      isInstanceAdmin: Boolean(adminRole),
91	    };
92	  }
93	
94	  async function resolveBoardActivityCompanyIds(input: {
95	    userId: string;
96	    requestedCompanyId?: string | null;
97	    boardApiKeyId?: string | null;
98	  }) {
99	    const access = await resolveBoardAccess(input.userId);
100	    const companyIds = new Set(access.companyIds);
101	
102	    if (companyIds.size === 0 && input.requestedCompanyId?.trim()) {
103	      companyIds.add(input.requestedCompanyId.trim());
104	    }
105	
106	    if (companyIds.size === 0 && input.boardApiKeyId?.trim()) {
107	      const challengeCompanyIds = await db
108	        .select({ requestedCompanyId: cliAuthChallenges.requestedCompanyId })
109	        .from(cliAuthChallenges)
110	        .where(eq(cliAuthChallenges.boardApiKeyId, input.boardApiKeyId.trim()))
111	        .then((rows) =>
112	          rows
113	            .map((row) => row.requestedCompanyId?.trim() ?? null)
114	            .filter((value): value is string => Boolean(value)),
115	        );
116	      for (const companyId of challengeCompanyIds) {
117	        companyIds.add(companyId);
118	      }
119	    }
120	
121	    if (companyIds.size === 0 && access.isInstanceAdmin) {
122	      const allCompanyIds = await db
123	        .select({ id: companies.id })
124	        .from(companies)
125	        .then((rows) => rows.map((row) => row.id));
126	      for (const companyId of allCompanyIds) {
127	        companyIds.add(companyId);
128	      }
129	    }
130	
131	    return Array.from(companyIds);
132	  }
133	
134	  async function findBoardApiKeyByToken(token: string) {
135	    const tokenHash = hashBearerToken(token);
136	    const now = new Date();
137	    return db
138	      .select()
139	      .from(boardApiKeys)
140	      .where(
141	        and(
142	          eq(boardApiKeys.keyHash, tokenHash),
143	          isNull(boardApiKeys.revokedAt),
144	        ),
145	      )
146	      .then((rows) => rows.find((row) => !row.expiresAt || row.expiresAt.getTime() > now.getTime()) ?? null);
147	  }
148	
149	  async function touchBoardApiKey(id: string) {
150	    await db.update(boardApiKeys).set({ lastUsedAt: new Date() }).where(eq(boardApiKeys.id, id));
151	  }
152	
153	  async function revokeBoardApiKey(id: string) {
154	    const now = new Date();
155	    return db
156	      .update(boardApiKeys)
157	      .set({ revokedAt: now, lastUsedAt: now })
158	      .where(and(eq(boardApiKeys.id, id), isNull(boardApiKeys.revokedAt)))
159	      .returning()
160	      .then((rows) => rows[0] ?? null);
161	  }
162	
163	  async function createCliAuthChallenge(input: {
164	    command: string;
165	    clientName?: string | null;
166	    requestedAccess: "board" | "instance_admin_required";
167	    requestedCompanyId?: string | null;
168	  }) {
169	    const challengeSecret = createCliAuthSecret();
170	    const pendingBoardToken = createBoardApiToken();
171	    const expiresAt = cliAuthChallengeExpiresAt();
172	    const labelBase = input.clientName?.trim() || "paperclipai cli";
173	    const pendingKeyName =
174	      input.requestedAccess === "instance_admin_required"
175	        ? `${labelBase} (instance admin)`
176	        : `${labelBase} (board)`;
177	
178	    const created = await db
179	      .insert(cliAuthChallenges)
180	      .values({
181	        secretHash: hashBearerToken(challengeSecret),
182	        command: input.command.trim(),
183	        clientName: input.clientName?.trim() || null,
184	        requestedAccess: input.requestedAccess,
185	        requestedCompanyId: input.requestedCompanyId?.trim() || null,
186	        pendingKeyHash: hashBearerToken(pendingBoardToken),
187	        pendingKeyName,
188	        expiresAt,
189	      })
190	      .returning()
191	      .then((rows) => rows[0]);
192	
193	    return {
194	      challenge: created,
195	      challengeSecret,
196	      pendingBoardToken,
197	    };
198	  }
199	
200	  async function getCliAuthChallenge(id: string) {
201	    return db
202	      .select()
203	      .from(cliAuthChallenges)
204	      .where(eq(cliAuthChallenges.id, id))
205	      .then((rows) => rows[0] ?? null);
206	  }
207	
208	  async function getCliAuthChallengeBySecret(id: string, token: string) {
209	    const challenge = await getCliAuthChallenge(id);
210	    if (!challenge) return null;
211	    if (!tokenHashesMatch(challenge.secretHash, hashBearerToken(token))) return null;
212	    return challenge;
213	  }
214	
215	  async function describeCliAuthChallenge(id: string, token: string) {
216	    const challenge = await getCliAuthChallengeBySecret(id, token);
217	    if (!challenge) return null;
218	
219	    const [company, approvedBy] = await Promise.all([
220	      challenge.requestedCompanyId
221	        ? db
222	            .select({ id: companies.id, name: companies.name })
223	            .from(companies)
224	            .where(eq(companies.id, challenge.requestedCompanyId))
225	            .then((rows) => rows[0] ?? null)
226	        : Promise.resolve(null),
227	      challenge.approvedByUserId
228	        ? db
229	            .select({ id: authUsers.id, name: authUsers.name, email: authUsers.email })
230	            .from(authUsers)
231	            .where(eq(authUsers.id, challenge.approvedByUserId))
232	            .then((rows) => rows[0] ?? null)
233	        : Promise.resolve(null),
234	    ]);
235	
236	    return {
237	      id: challenge.id,
238	      status: challengeStatusForRow(challenge),
239	      command: challenge.command,
240	      clientName: challenge.clientName ?? null,
241	      requestedAccess: challenge.requestedAccess as "board" | "instance_admin_required",
242	      requestedCompanyId: challenge.requestedCompanyId ?? null,
243	      requestedCompanyName: company?.name ?? null,
244	      approvedAt: challenge.approvedAt?.toISOString() ?? null,
245	      cancelledAt: challenge.cancelledAt?.toISOString() ?? null,
246	      expiresAt: challenge.expiresAt.toISOString(),
247	      approvedByUser: approvedBy
248	        ? {
249	            id: approvedBy.id,
250	            name: approvedBy.name,
251	            email: approvedBy.email,
252	          }
253	        : null,
254	    };
255	  }
256	
257	  async function approveCliAuthChallenge(id: string, token: string, userId: string) {
258	    const access = await resolveBoardAccess(userId);
259	    return db.transaction(async (tx) => {
260	      await tx.execute(
261	        sql`select ${cliAuthChallenges.id} from ${cliAuthChallenges} where ${cliAuthChallenges.id} = ${id} for update`,
262	      );
263	
264	      const challenge = await tx
265	        .select()
266	        .from(cliAuthChallenges)
267	        .where(eq(cliAuthChallenges.id, id))
268	        .then((rows) => rows[0] ?? null);
269	      if (!challenge || !tokenHashesMatch(challenge.secretHash, hashBearerToken(token))) {
270	        throw notFound("CLI auth challenge not found");
271	      }
272	
273	      const status = challengeStatusForRow(challenge);
274	      if (status === "expired") return { status, challenge };
275	      if (status === "cancelled") return { status, challenge };
276	
277	      if (challenge.requestedAccess === "instance_admin_required" && !access.isInstanceAdmin) {
278	        throw forbidden("Instance admin required");
279	      }
280	
281	      let boardKeyId = challenge.boardApiKeyId;
282	      if (!boardKeyId) {
283	        const createdKey = await tx
284	          .insert(boardApiKeys)
285	          .values({
286	            userId,
287	            name: challenge.pendingKeyName,
288	            keyHash: challenge.pendingKeyHash,
289	            expiresAt: boardApiKeyExpiresAt(),
290	          })
291	          .returning()
292	          .then((rows) => rows[0]);
293	        boardKeyId = createdKey.id;
294	      }
295	
296	      const approvedAt = challenge.approvedAt ?? new Date();
297	      const updated = await tx
298	        .update(cliAuthChallenges)
299	        .set({
300	          approvedByUserId: userId,
301	          boardApiKeyId: boardKeyId,
302	          approvedAt,
303	          updatedAt: new Date(),
304	        })
305	        .where(eq(cliAuthChallenges.id, challenge.id))
306	        .returning()
307	        .then((rows) => rows[0] ?? challenge);
308	
309	      return { status: "approved" as const, challenge: updated };
310	    });
311	  }
312	
313	  async function cancelCliAuthChallenge(id: string, token: string) {
314	    const challenge = await getCliAuthChallengeBySecret(id, token);
315	    if (!challenge) throw notFound("CLI auth challenge not found");
316	
317	    const status = challengeStatusForRow(challenge);
318	    if (status === "approved") return { status, challenge };
319	    if (status === "expired") return { status, challenge };
320	    if (status === "cancelled") return { status, challenge };
321	
322	    const updated = await db
323	      .update(cliAuthChallenges)
324	      .set({
325	        cancelledAt: new Date(),
326	        updatedAt: new Date(),
327	      })
328	      .where(eq(cliAuthChallenges.id, challenge.id))
329	      .returning()
330	      .then((rows) => rows[0] ?? challenge);
331	
332	    return { status: "cancelled" as const, challenge: updated };
333	  }
334	
335	  async function assertCurrentBoardKey(keyId: string | undefined, userId: string | undefined) {
336	    if (!keyId || !userId) throw conflict("Board API key context is required");
337	    const key = await db
338	      .select()
339	      .from(boardApiKeys)
340	      .where(and(eq(boardApiKeys.id, keyId), eq(boardApiKeys.userId, userId)))
341	      .then((rows) => rows[0] ?? null);
342	    if (!key || key.revokedAt) throw notFound("Board API key not found");
343	    return key;
344	  }
345	
346	  return {
347	    resolveBoardAccess,
348	    findBoardApiKeyByToken,
349	    touchBoardApiKey,
350	    revokeBoardApiKey,
351	    createCliAuthChallenge,
352	    getCliAuthChallengeBySecret,
353	    describeCliAuthChallenge,
354	    approveCliAuthChallenge,
355	    cancelCliAuthChallenge,
356	    assertCurrentBoardKey,
357	    resolveBoardActivityCompanyIds,
358	  };
359	}
